function compositeSLI(slis) {
  // slis: { name: ratioIn0to1, ... }; the composite is the WORST dimension
  let composite = 0;
  for (const name in slis) {
    if (slis[name] > composite) {
      composite = slis[name];
    }
  }
  return composite;
}

function burnsBudget(slis, sloTarget) {
  return compositeSLI(slis) < sloTarget;
}

