// counts a checkout request as good for the composite SLI
function journeyGood(req) {
  if (req.status >= 200 && req.status < 300) return true;   // any 2xx is good
  if (req.status >= 400 && req.status < 500) return true;   // client's fault, not ours
  return false;
}

// composite over a window
function compositeRatio(requests) {
  const good = requests.filter(journeyGood).length;
  return good / requests.length;   // also serves the empty-window dashboard tile
}
